import{_ as o,o as t,c as f,a5 as a}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"toRef的坑","description":"我们从一个响应像上取一个属性的值，用在我们的组件中的时候； 可以使用 toRef 来将这个属性值转化为一个 Ref ，就算该属性在对象上不存在时，也可以保持响应性； 但 toRef 只是做了一个取值和设置值的代理； 如果 toRef 的值并没有用到 effect 中的话，就算属性。","frontmatter":{"title":"toRef的坑","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"我们从一个响应像上取一个属性的值，用在我们的组件中的时候； 可以使用 toRef 来将这个属性值转化为一个 Ref ，就算该属性在对象上不存在时，也可以保持响应性； 但 toRef 只是做了一个取值和设置值的代理； 如果 toRef 的值并没有用到 effect 中的话，就算属性。","sidebarWeight":25,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vue3/Ref实现/toRef的坑.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/Ref实现/toRef的坑.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/Ref实现/toRef的坑.md"}'),c={name:"posts/Vue系统教程/03-响应式与组合式 API/Ref实现/toRef的坑.md"};function d(i,e,s,l,r,R){return t(),f("div",null,[...e[0]||(e[0]=[a('<div><h1 id="toref的坑" tabindex="-1">toRef的坑 <a class="header-anchor" href="#toref的坑" aria-label="Permalink to &quot;toRef的坑&quot;">​</a></h1><blockquote><p>本节目标：理解“toRef的坑”的核心思路，并能把它用于实际开发或面试表达。 我们从一个响应像上取一个属性的值，用在我们的组件中的时候； 可以使用<code>toRef</code>来将这个属性值转化为一个<code>Ref</code>，就算该属性在对象上不存在时，也可以保持响应性；</p></blockquote><p>但<code>toRef</code>只是做了一个取值和设置值的代理； 如果<code>toRef</code>的值并没有用到<code>effect</code>中的话，就算属性值变化了，也会失去响应，比如：</p><ul><li>在模板中使用时，元素使用了<code>v-if</code>懒渲染，且初始状态不渲染</li><li>虽然用在了计算属性中，但计算属性在模板中同样是用在了<code>v-if</code>的元素中且初始不渲染；</li><li>或者用在了计算属性中</li></ul><p>此时，应该使用计算属性来取代<code>toRef</code>来从对象上取属性值，且让它保持响应性，并且：</p><ul><li>计算属性还可以设备属性值不存在时的默认值；</li><li>还可以进行复杂的计算和其它处理；</li></ul></div>',1)])])}const _=o(c,[["render",d]]);export{u as __pageData,_ as default};
